<?php
declare(strict_types=1);require dirname(__DIR__,2).'/src/bootstrap.php';
use Sedema\Authorization;use Sedema\Csrf;use Sedema\Logistics\LogisticsContext;use Sedema\Logistics\LogisticsPage;
$c=LogisticsContext::boot();$user=$c['user'];Authorization::require($user,'logistics.manage');$repo=$c['repository'];$vehicles=$repo->vehicles(false);LogisticsPage::begin('Flota','vehicles',$user);?>
<section class="inventory-heading"><div><p class="section-kicker">Recursos logísticos</p><h2>Vehículos</h2><p>Alta, disponibilidad y mantenimiento de la flota.</p></div></section>
<div class="inventory-form-columns"><form class="inventory-form" method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="save-vehicle"><section class="form-section"><div class="form-section-heading"><span>01</span><div><h3>Registrar vehículo</h3><p>La capacidad se expresa en la unidad operativa definida por la empresa.</p></div></div><div class="form-grid single-column"><div class="field"><label for="plate">Matrícula *</label><input id="plate" name="matricula" maxlength="20" required></div><div class="field"><label for="model">Modelo *</label><input id="model" name="modelo" maxlength="100" required></div><div class="field"><label for="capacity">Capacidad de carga *</label><input id="capacity" name="capacidadCarga" type="number" min="0.001" step="0.001" required></div><div class="field"><label for="vstate">Estado *</label><select id="vstate" name="estado"><option value="DISPONIBLE">Disponible</option><option value="EN_MANTENIMIENTO">En mantenimiento</option></select></div></div><button class="button button-primary button-full">Guardar vehículo</button></section></form>
<section class="inventory-panel"><div class="panel-title-row"><div><h3>Flota registrada</h3><p><?=count($vehicles)?> vehículos</p></div></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Matrícula</th><th>Modelo</th><th>Capacidad</th><th>Estado</th><th>Activo</th><th></th></tr></thead><tbody><?php foreach($vehicles as $v):?><tr><td><strong><?=e((string)$v['matricula'])?></strong></td><td><?=e((string)$v['modelo'])?></td><td><?=e((string)$v['capacidadCarga'])?></td><td><?=e(str_replace('_',' ',(string)$v['estado']))?></td><td><?=(int)$v['activo']===1?'Sí':'No'?></td><td class="table-actions"><?php if($v['estado']!=='OCUPADO'):?><a href="vehicle.php?id=<?=(int)$v['idVehiculo']?>">Editar</a><form class="inline-form" method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="toggle-vehicle"><input type="hidden" name="idVehiculo" value="<?=(int)$v['idVehiculo']?>"><input type="hidden" name="active" value="<?=(int)$v['activo']===1?'0':'1'?>"><button class="link-button" type="submit"><?=(int)$v['activo']===1?'Dar de baja':'Reactivar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php LogisticsPage::end();
